// Module-boundary check: tags + allowed dependency rules (like Nx depConstraints)
const projects = {
  'booking-feature': ['type:feature', 'scope:booking'],
  'booking-ui': ['type:ui', 'scope:booking'],
  'booking-data': ['type:data-access', 'scope:booking'],
  'checkin-feature': ['type:feature', 'scope:checkin'],
  'shared-util': ['type:util', 'scope:shared'],
};
// source tag -> tags the source may depend on
const rules = {
  'type:feature': ['type:ui', 'type:data-access', 'type:util'],
  'type:ui': ['type:ui', 'type:util'],
  'type:data-access': ['type:data-access', 'type:util'],
  'type:util': ['type:util'],
  'scope:booking': ['scope:booking', 'scope:shared'],
  'scope:checkin': ['scope:checkin', 'scope:shared'],
  'scope:shared': ['scope:shared'],
};
const imports = [
  ['booking-feature', 'booking-ui'],
  ['booking-ui', 'shared-util'],
  ['booking-ui', 'booking-data'],      // ui must not use data-access
  ['checkin-feature', 'booking-data'], // crosses domains
];
for (const [from, to] of imports) {
  const problems = [];
  for (const st of projects[from]) {
    // every rule of the source must be satisfied by the target's tags
    const ok = projects[to].some(t => rules[st].includes(t));
    if (!ok) problems.push(st + ' cannot depend on ' + projects[to].join('+'));
  }
  console.log(from + ' -> ' + to + ': ' + (problems.length ? 'ERROR ' + problems.join('; ') : 'ok'));
}

// Why interpolation is safe: text is escaped; HTML sinks need a sanitizer
function escapeText(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
// tiny allowlist "sanitizer": keep only <b> and <i> tags without attributes
function sanitizeHtml(s) {
  return s.replace(/<(\/?)(\w+)[^>]*>/g, (m, slash, tag) =>
    ['b', 'i'].includes(tag.toLowerCase()) && m === '<' + slash + tag + '>' ? m : '');
}
// URL sink: neutralise javascript: links
function sanitizeUrl(u) {
  return /^(https?:|mailto:|\/)/i.test(u.trim()) ? u : 'unsafe:' + u;
}
