// Cookie-to-header XSRF check (double submit)
const serverSessions = { sess1: 'tok-abc123' };  // token the server issued
function handle(req) {
  if (['GET', 'HEAD'].includes(req.method)) return 'allowed (read only)';
  const cookieTok = req.cookies['XSRF-TOKEN'];
  const headerTok = req.headers['X-XSRF-TOKEN'];
  // header must exist and match both the cookie and the server's record
  if (headerTok && headerTok === cookieTok && headerTok === serverSessions[req.cookies.session])
    return 'allowed';
  return 'rejected 403';
}
const cookies = { session: 'sess1', 'XSRF-TOKEN': 'tok-abc123' };
const reqs = [
  { name: 'own page POST', method: 'POST', cookies, headers: { 'X-XSRF-TOKEN': 'tok-abc123' } },
  { name: 'evil site POST', method: 'POST', cookies, headers: {} }, // browser sends cookies, cannot read token
  { name: 'evil guess', method: 'POST', cookies, headers: { 'X-XSRF-TOKEN': 'guess' } },
  { name: 'GET', method: 'GET', cookies, headers: {} },
];
for (const r of reqs) console.log(r.name.padEnd(15), r.method.padEnd(5), handle(r));

// Table pipeline: filter -> sort (copy) -> paginate with clamping
const rows = [
  { id: 1, name: 'Mia', age: 31 }, { id: 2, name: 'Omar', age: 25 },
  { id: 3, name: 'Anna', age: 40 }, { id: 4, name: 'Ali', age: 25 },
  { id: 5, name: 'Zoe', age: 19 }, { id: 6, name: 'Amy', age: 52 },
];
function view(state) {
  const q = state.query.toLowerCase();
  const filtered = rows.filter(r => r.name.toLowerCase().includes(q));
  const dir = state.dir === 'asc' ? 1 : -1;
  const sorted = [...filtered].sort((a, b) => {          // copy: never mutate source
    const x = a[state.key], y = b[state.key];
    const c = typeof x === 'number' ? x - y : String(x).localeCompare(y);
    return c * dir || a.id - b.id;                       // id tie-break = stable
  });
  const pageCount = Math.max(1, Math.ceil(sorted.length / state.size));
  const page = Math.min(state.page, pageCount);          // clamp
  const start = (page - 1) * state.size;
  return { pageCount, page, items: sorted.slice(start, start + state.size).map(r => r.name + ':' + r.age) };
}
console.log('rows:', rows.length);
console.log(JSON.stringify(view({ query: '', key: 'age', dir: 'asc', size: 2, page: 1 })));
