console.log(JSON.stringify(view({ query: 'a', key: 'name', dir: 'desc', size: 2, page: 9 })));

// Kanban move: immutable update + fractional rank
const board = {
  todo: [{ id: 'a', rank: 1 }, { id: 'b', rank: 2 }, { id: 'c', rank: 3 }],
  done: [{ id: 'd', rank: 1 }, { id: 'e', rank: 2 }],
};
function move(b, from, to, id, index) {
  const card = b[from].find(c => c.id === id);
  const target = b[to].filter(c => c.id !== id);
  const prev = target[index - 1], next = target[index];
  // rank between neighbours: only this one card changes
  const rank = prev && next ? (prev.rank + next.rank) / 2
    : prev ? prev.rank + 1 : next ? next.rank - 1 : 1;
  const moved = { ...card, rank };
  target.splice(index, 0, moved);
  return { ...b, [from]: b[from].filter(c => c.id !== id), [to]: target }; // new objects
}
const show = b => Object.entries(b).map(([k, v]) => k + '=[' + v.map(c => c.id + '@' + c.rank).join(',') + ']').join(' ');
console.log('before:', show(board));
const after = move(board, 'todo', 'done', 'b', 1);
console.log('after :', show(after));
console.log('original untouched:', show(board) === 'todo=[a@1,b@2,c@3] done=[d@1,e@2]');
